package main

import (
	"errors"
	"fmt"
)

// ここに divide を定義する

func main() {
	var a, b int
	fmt.Scan(&a, &b)
	// divide を呼び、エラーなら error、正常なら商を出力する
}

quiz.answer:
package main

import (
	"errors"
	"fmt"
)

func divide(a, b int) (int, error) {
	if b == 0 {
		return 0, errors.New("division by zero")
	}
	return a / b, nil
}

func main() {
	var a, b int
	fmt.Scan(&a, &b)
	result, err := divide(a, b)
	if err != nil {
		fmt.Println("error")
		return
	}
	fmt.Println(result)
}
